using Microsoft.AspNetCore.Mvc.Controllers;
using Microsoft.AspNetCore.Mvc.Abstractions;

namespace SmartCampus.Api.ApiDocumentation;

internal sealed record ApiOperationDetails(string Tag, string Summary, string Description);

/// <summary>Human-readable OpenAPI text kept next to the OpenAPI pipeline.</summary>
internal static class ApiOperationDocumentation
{
    private const string JwtErrors = "Errors: 400 for invalid input; 401 without a valid JWT; 403 when the JWT role is not allowed; 404 when a referenced record does not exist; 409 when the requested state or concurrency version conflicts. Only statuses applicable to the operation are returned.";
    private const string TourStorageBoundary = "A Tour created under ADR-0034 stores an exact RouteRevision, assigned Operator and robot reservation; legacy Tours store none of them, and no Tour has a READY snapshot yet.";

    private static readonly IReadOnlyDictionary<string, (string Summary, string Description)> Operations =
        new Dictionary<string, (string, string)>(StringComparer.Ordinal)
        {
            ["RouteRevisionsController.List"] = ("[Tour Staff/Technical Staff] Liệt kê tuyến VERSIONED", "Pages current revisions of VERSIONED routes only, including unsubmitted drafts; it never mixes legacy catalog rows or emits multiple history rows for one Route. Requires Staff or TechnicalStaff. Supports `search`, `mapVersionId`, `isActive`, `page`, `size` (1–100), and `sort` (`name`, `-name`, `createdAt`, `-createdAt`). Each item is the full current revision view with exact map version/key, submit state, effective navigation result/source TestRun, dwell subtotal, and incomplete content/audio duration status. Invalid paging/sort returns 400; missing JWT 401; unsupported role 403. A TestRun is manual navigation evidence, not duration completion or Tour READY. " + JwtErrors),
            ["AdminAccountsController.List"] = ("[Admin] Liệt kê và tìm tài khoản", "Lists safe account summaries with paging and optional search/sort. Requires the Admin JWT role. `page` and `size` control the page; `expand` is unsupported. Does not expose credentials. " + JwtErrors),
            ["AdminAccountsController.Create"] = ("[Admin] Tạo tài khoản người dùng", "Creates one account using `username`, `fullName`, `role`, and `initialPassword`. Supported roles are the backend application roles, including `TechnicalStaff`; each account has exactly one role. Requires Admin. A normalized duplicate username conflicts (409); invalid or unsupported role/input is 400. " + JwtErrors),
            ["AdminAccountsController.Update"] = ("[Admin] Sửa họ tên tài khoản", "Body `{fullName}`. Changes only the display name of the account identified by `id`; username, role, password and active state are unchanged. Records `ACCOUNT_UPDATED` in the audit log when the name changes. Requires Admin. A missing account returns 404; a blank or too long name returns 400. " + JwtErrors),
            ["AccountController.Get"] = ("[Mọi vai trò] Xem hồ sơ của tôi", "Returns the profile of the account in the JWT; there is no `{id}`, so another user's profile cannot be addressed. Allowed for Admin, Staff, TechnicalStaff and Representative. A token whose account no longer exists returns 401; a deactivated account returns 403. " + JwtErrors),
            ["AccountController.Update"] = ("[Mọi vai trò] Sửa họ tên của tôi", "Body `{fullName}`. Changes only the display name of the account in the JWT and records `PROFILE_UPDATED` when it changes. Allowed for Admin, Staff, TechnicalStaff and Representative. A blank or too long name returns 400; an account that no longer exists returns 401, a deactivated one 403. " + JwtErrors),
            ["AccountController.ChangePassword"] = ("[Mọi vai trò] Đổi mật khẩu của tôi", "Body `{currentPassword, newPassword}`; unknown fields are rejected. The new password must have 12 to 128 characters and differ from the current one. A wrong current password returns 400 and counts against the same per-account attempt budget as login. On success every refresh token of the account is revoked, so each device must sign in again; issued access tokens stay valid until they expire. Records `PASSWORD_CHANGED`. " + JwtErrors),
            ["AdminAccountsController.Deactivate"] = ("[Admin] Vô hiệu hóa tài khoản", "Deactivates the account identified by `id`; repeat calls are idempotent where allowed by the account lifecycle. Requires Admin. A missing account returns 404; a forbidden target returns 403. " + JwtErrors),
            ["AdminAccountsController.Reactivate"] = ("[Admin] Kích hoạt lại tài khoản", "Reactivates the account identified by `id` under the account lifecycle rules. Requires Admin. A missing account returns 404; a forbidden target returns 403. " + JwtErrors),

            ["RobotCredentialsController.Issue"] = ("[Technical Staff] Cấp khóa Fleet Sync lần đầu", "Issues a one-time Fleet Sync secret for an existing PHYSICAL robot that has no active credential. Body includes `requestId` and the robot's current `expectedRowVersion`; replay does not return the secret again. The plaintext is returned once with `Cache-Control: no-store`; only its hash is persisted. Credential metadata, confirmation reset and append-only audit entry commit atomically. Requires TechnicalStaff. Active credential returns 409; non-PHYSICAL or unknown robot returns 404. " + JwtErrors),
            ["RobotCredentialsController.Rotate"] = ("[Technical Staff] Cấp lại khóa Fleet Sync", "Replaces the active credential for a PHYSICAL robot, invalidating the old key and atomically clearing first-accepted confirmation. Body includes `requestId` and current `expectedRowVersion`; the new secret is returned once with `Cache-Control: no-store`, and replay never reveals it again. Requires TechnicalStaff. Missing active credential returns 409; stale row version returns 409; unknown robot returns 404. " + JwtErrors),
            ["RobotCredentialsController.Revoke"] = ("[Technical Staff/Admin] Thu hồi khóa Fleet Sync", "Revokes the active credential without issuing a replacement and atomically clears first-accepted confirmation while appending an audit entry. Body requires `requestId`, `expectedRowVersion` and a non-empty reason up to 500 characters. TechnicalStaff may revoke; Admin may revoke only as an emergency action. No active key returns 409; stale row version returns 409; unknown/non-PHYSICAL robot returns 404. " + JwtErrors),
            ["RobotCredentialsController.Get"] = ("[Technical Staff/Admin] Xem trạng thái và lịch sử khóa", "Returns safe credential status, issue/revocation metadata, hint and this robot's append-only credential audit history. Never returns plaintext or credential hash. Requires TechnicalStaff or Admin; Staff can read connection status only through the physical robot list. " + JwtErrors),

            ["StaffToursController.Robots"] = ("[Staff] Liệt kê robot cho Tour", "Lists active physical robots for one route revision with `usable` and a Vietnamese `blockReason`, using the same rule as create and slots: connection confirmed and latest deployment check PASS on the revision's exact map and SHA. " + JwtErrors),
            ["StaffToursController.ChangeCapacity"] = ("[Staff] Đổi sức chứa Tour", "Body `{requestId, expectedRowVersion, capacity}`. SCHEDULED or READY before Start; READY stays READY. `capacity` is 1..`Tours:MaxCapacity`; below the held seats is 409 `CAPACITY_BELOW_HELD`. Audited (ADR-0048)."),
            ["StaffToursController.ChangeOperator"] = ("[Staff] Đổi người vận hành Tour", "Body `{requestId, expectedRowVersion, operatorUserId}`. SCHEDULED or READY before Start; READY stays READY. The new account must be an active Staff account. Audited (ADR-0048)."),
            ["RouteRevisionsController.RerunQueue"] = ("[Technical Staff] Xem tuyến cần chạy lại", "Lists current revisions of open VERSIONED routes whose effective PASS has no measurement basis, so they cannot be scheduled until a new test run is recorded (ADR-0048)."),
            ["StaffToursController.Slots"] = ("[Staff] Xem ca trống để tạo Tour", "Lists every configured shift (`Tours:Shifts`) for each date between `from` and `to` (Vietnam dates, at most 31 days) for one tested route revision and robot. Each item has `shiftCode`, `shiftName`, `time` (Tour start, shift opening + 15 minutes), `startsAt`, `reservationStartsAt/EndsAt` (the whole shift), `maxDurationSeconds`, `registrationClosesAt`, and `available` or a `reasonCode` (`LEAD_TIME_TOO_SHORT`, `ROUTE_TEST_REMEASURE_REQUIRED`, `ROUTE_TOO_LONG_FOR_SHIFT`, `RESERVATION_OVERLAP`) with Vietnamese text. The response carries `recommendedMaxSeconds`. Uses the same calculation as create, which rechecks at save. " + JwtErrors),
            ["StaffToursController.Shifts"] = ("[Staff] Xem các ca của từng ngày", "Lists the configured shifts for each date between `from` and `to` (Vietnam dates, at most 31 days), without judging a route or robot, so the calendar can draw them. Each item has `code`, `name`, `startsAt`/`endsAt` (robot hold), `tourStartsAt`, `time`, `maxDurationSeconds` and `block` (`{id, scope, reason}`, null when open; `scope` is DAY or SHIFT); the response carries `recommendedMaxSeconds` and `quickTourWaitMinutes` (how long a quick Tour waits to be started, ADR-0053). Requires Staff. " + JwtErrors),
            ["AdminScheduleBlocksController.List"] = ("[Admin] Xem các ca và khoá lịch", "Same shape as the Staff shift list: each date between `from` and `to` (Vietnam dates, at most 31 days) with its configured shifts and any active `block`. Requires Admin. " + JwtErrors),
            ["AdminScheduleBlocksController.Create"] = ("[Admin] Khoá một ngày hoặc một ca", "Body `{requestId, date, shiftCode, reason}`; `shiftCode` null closes the whole day and `reason` is required. Records `SCHEDULE_BLOCK_CREATED`; a retry with the same `requestId` returns the same block. 409 `SHIFT_HAS_TOURS` with `errors.blockers` naming each Tour not cancelled in that day or shift; 409 `SCHEDULE_BLOCK_EXISTS` when the shift or day is already closed, including a day with a separately closed shift. Requires Admin. " + JwtErrors),
            ["AdminScheduleBlocksController.Remove"] = ("[Admin] Gỡ khoá lịch", "Body `{requestId}`. Stamps who removed the block and when, keeping the row, and records `SCHEDULE_BLOCK_REMOVED`. 404 for an unknown block; 409 `SCHEDULE_BLOCK_ALREADY_REMOVED`. Requires Admin. " + JwtErrors),

            ["StaffNotificationsController.List"] = ("[Staff] Xem thông báo từ Technical Staff", "Lists the newest Technical Staff outcomes Staff acts on, newest first: POI verified or rejected, Route test PASS or FAIL, map deployment check and robot inspection released. `size` 1..50 (default 30). Each row has `id`, `occurredAt`, `action`, `resultCode`, `targetId` (the POI proposal, Route, map version or robot), `subject`, `revisionNumber`, `robotCode` and `actorName`; `targetId` and `subject` are null when the target is gone. A read projection of the audit log: no raw audit data, no read state, no push event. Requires Staff. " + JwtErrors),
            ["AdminAuditLogsController.List"] = ("[Admin] Xem nhật ký hệ thống", "Lists append-only audit entries newest first with optional `action`, `actor`, `from` and `to` filters plus `page` and `size` (at most 100). Returns safe columns only; raw audit data is never exposed. Read-only. " + JwtErrors),

            ["RobotCredentialsController.ListAudit"] = ("[Admin] Lọc nhật ký khóa robot", "Lists append-only robot credential audit rows with optional action, robotCode, actorUserId and time-range filters plus `page`. Data contains a safe hint, reason and source, never the secret or hash. Admin only; no edit/delete API exists. " + JwtErrors),
            ["RobotCredentialsController.ListStaffConnectionStatus"] = ("[Staff] Xem trạng thái kết nối robot vật lý", "Returns safe connection state and latest in-memory sync receipt for registered physical robots. Does not expose credential status, metadata, hints, hashes or secrets. Requires Staff. " + JwtErrors),

            ["MapPoiController.UploadMap"] = ("[Technical Staff] Upload gói ROS map và tạo phiên bản", "Validates a ROS map ZIP and stores an immutable map version for `areaKey`/`areaName`. Multipart fields: `requestId` (stable retry key for the same payload) and `package`; the server computes SHA-256 and allocates the next version under the area transaction lock. New areas are created with their first version; existing area keys must retain their stored display name. Changing the payload requires a new requestId. Requires TechnicalStaff. Uploading validates and stores a package only: it does not deploy the map to a robot or establish deployment evidence. Invalid/oversized packages return 400; area name/idempotency/version conflicts return 409; role failures return 403. " + JwtErrors),
            ["MapPoiController.PreviewPoiImport"] = ("[Technical Staff] Xem trước nhập POI từ file", "Multipart fields: `mapVersionId`, `robotCode` and `files` (.yaml/.yml, at most 50 and 64 KB each, or one ZIP with them at its root). Returns per-file parsed pose, verified flag, action (CREATE, NEW_REVISION, NO_CHANGE) or an error code with a Vietnamese message. Writes nothing. Requires TechnicalStaff. " + JwtErrors),
            ["MapPoiController.ImportPois"] = ("[Technical Staff] Nhập POI từ file ghi pose", "Same fields as preview plus `requestId` and required `evidenceNote`. All-or-nothing: any failing file returns 409 POI_IMPORT_INVALID with per-file errors and imports nothing. A verified file records a POSE_CAPTURE result that claims no reach, stop, localization or camera observation and stores the raw file and SHA-256; an unverified file goes to the Technical verification queue. Retrying the same request returns the same result; the same file on the same map version is NO_CHANGE. Requires TechnicalStaff. " + JwtErrors),
            ["MapPoiController.DeactivateRobot"] = ("[Technical Staff] Ngừng sử dụng robot", "In one transaction records who stopped the robot and why, revokes its active key and clears its map assignment. Body: `requestId`, `expectedRowVersion`, required `reason`. Returns the SCHEDULED/READY Tours reserved on it; none is cancelled. IsDispatchEnabled is untouched. " + JwtErrors),
            ["MapPoiController.SetRobotDispatch"] = ("[Technical Staff] Bật/tắt điều phối robot", "Body `{requestId, expectedRowVersion, enabled, reason, evidenceRef}`. Turning off always works, even from a stale page. Turning on needs `evidenceRef` (the GATE A record) and an active robot (`ROBOT_DEACTIVATED`) with a key (`ROBOT_CREDENTIAL_REQUIRED`), an assigned map (`ROBOT_MAP_REQUIRED`), a passing latest deployment check on that map (`ROBOT_DEPLOYMENT_CHECK_REQUIRED`) and no pending inspection (`ROBOT_NEEDS_INSPECTION`); old version `STALE_VERSION` (409). Audited as `ROBOT_DISPATCH_CHANGED`; a repeat with the same `requestId` replays. Does not stop a robot already moving. " + JwtErrors),
            ["MapPoiController.ReleaseRobotInspection"] =("[Technical Staff] Trả robot sau kiểm tra tại chỗ", "Body `{requestId, expectedRowVersion, reason}`. Clears `CurrentTourId` and `NeedsInspection` after an on-site check, with an audit row. Refused while the Tour holding the robot has not ended (`ROBOT_TOUR_ACTIVE`), while it has an open or unreconciled command (`ROBOT_COMMAND_OPEN`), or when it is not held (`ROBOT_NOT_HELD`); old version `STALE_VERSION` (409). " + JwtErrors),
            ["MapPoiController.ActivateRobot"] = ("[Technical Staff] Kích hoạt lại robot", "Clears the deactivation record only. Technical Staff must issue a new key and assign a map again. Body: `requestId`, `expectedRowVersion`. " + JwtErrors),
            ["MapPoiController.ListRobotAffectedTours"] = ("[Technical Staff] Xem Tour bị ảnh hưởng", "Lists SCHEDULED/READY Tours reserved on the robot whose route revision uses another map than `mapVersionId`, or all of them without it. Read-only. " + JwtErrors),
            ["MapPoiController.ListMapAreas"] = ("[Technical Staff] Liệt kê khu vực map", "Returns the complete read-only list of persisted map areas (`areaKey`, `displayName`), independent of map-version list paging. Uses existing MapAreas; does not create a CRUD workflow. Requires TechnicalStaff. " + JwtErrors),
            ["MapPoiController.ListPhysicalRobots"] = ("[Technical Staff/Admin/Staff] Liệt kê robot vật lý", "Returns safe credential metadata, the inspection hold (`needsInspection`, `currentTourId`, `currentTourName`, `currentTourState`; ADR-0043 D13), first-accepted connection confirmation, current in-memory sync freshness, the database-assigned valid MapVersion and latest cross-map deployment check. Admin and Staff are read-only; only TechnicalStaff may change map assignment. No credential hash, secret, or unrelated settings are returned. Map checks remain manual observations; PASS requires persisted connection confirmation while FAIL remains allowed without one. " + JwtErrors),
            ["MapPoiController.AssignRobotMap"] = ("[Technical Staff] Gán phiên bản bản đồ cho robot", "Assigns a valid uploaded map version to a PHYSICAL robot. Body requires `requestId`, `expectedRowVersion` and `mapVersionId`; mapKey/frameId are derived from the immutable MapVersion, including when its technical check is not PASS. The transaction updates only the three assignment columns and appends an audit row. It does not change credentials or first-accepted confirmation. A stale rowVersion or conflicting replay returns 409. " + JwtErrors),
            ["MapPoiController.ClearRobotMap"] = ("[Technical Staff] Gỡ gán bản đồ khỏi robot", "Clears a PHYSICAL robot's assigned map context. Body requires `requestId` and `expectedRowVersion`. The transaction clears the three assignment columns and appends an audit row; subsequent Fleet Sync reports are rejected as unconfigured until a map is assigned again. " + JwtErrors),
            ["MapPoiController.RegisterPhysicalRobot"] = ("[Technical Staff] Đăng ký danh tính robot vật lý", "Registers only a robot identity using `robotCode` and `displayName`. RobotCode follows Fleet Sync v1 format and is limited to 100 characters; displayName is required and limited to 150. The server trims both values, sets `SourceType=PHYSICAL`, creates an unassigned, dispatch-disabled Robot row with a null credential hash, and appends an actor/time audit record in the same save transaction. Duplicate RobotCode returns 409 through the database unique constraint. Only TechnicalStaff may call this API. It does not provision a credential, connect to ROS2, mark the robot online/ready, or authorize dispatch. After issuing a credential, assign an uploaded map version to provide Fleet Sync context. " + JwtErrors),
            ["MapPoiController.IssuePhysicalRobotCredential"] = ("[Technical Staff] Cấp credential Fleet Sync lần đầu", "Compatibility endpoint addressed by physical robot ID. Issues a one-time credential only when the registered PHYSICAL robot has no active key. Body includes `requestId` and `expectedRowVersion`; plaintext is returned once with `Cache-Control: no-store`, only the hash is stored, and replay never returns the secret again. Credential metadata, confirmation reset and append-only audit commit atomically. Active key returns 409; stale row version/replayed request returns 409. The canonical endpoint uses RobotCode under `/api/technical/robots/{robotCode}/credential`. " + JwtErrors),
            ["MapPoiController.RotatePhysicalRobotCredential"] = ("[Technical Staff] Chủ động cấp lại credential Fleet Sync", "Compatibility endpoint addressed by physical robot ID. Replaces the current PHYSICAL robot credential and resets all three persisted first-accepted confirmation fields in the same transaction. Body includes `requestId` and `expectedRowVersion`; the new plaintext is returned once with `Cache-Control: no-store`, the old token stops authenticating, and a replay never reveals the secret again. Requires TechnicalStaff. The canonical endpoint uses RobotCode under `/api/technical/robots/{robotCode}/credential/rotate`. " + JwtErrors),
            ["MapPoiController.ListMaps"] = ("[Tour Staff/Technical Staff] Xem các phiên bản map", "Lists map metadata and backend-calculated technical check / POI-preparation state, optionally filtered by `areaKey`, with `take` capped by backend validation. Response includes `technicalCheckStatus`, `canUseForPoiPreparation`, block reason code/text, and the robot/time/check evidence used. Eligibility uses the latest check per exact map-version/physical-robot pair and requires matching package SHA-256 plus localization and display PASS; a newer FAIL supersedes that robot's earlier PASS. A passing check on another map version is not inherited. `currentlyDeployedOn` separately reports physical robots whose latest deployment check across all maps points to this exact map version with matching checksum and both observations passed. This read-only marker does not change historical POI eligibility or block selection. Read permission is Staff or TechnicalStaff. This is recorded human evidence, not live robot inspection. Invalid `take` returns 400. " + JwtErrors),
            ["MapPoiController.GetMap"] = ("[Tour Staff/Technical Staff] Xem chi tiết phiên bản map", "Reads immutable map metadata and the same backend-calculated technical check / POI-preparation state returned by the list operation, including reason and source evidence. Eligibility uses the latest check per exact map-version/physical-robot pair and requires matching checksum, localization and display PASS. `currentlyDeployedOn` separately lists physical robots whose latest cross-map check points to this version with matching checksum and both observations passed. A recorded check is historical human-entered evidence, not live robot inspection; this marker does not change POI eligibility. Current permission is Staff or TechnicalStaff. Missing version returns 404. " + JwtErrors),
            ["MapPoiController.DownloadMap"] = ("[Tour Staff/Technical Staff] Tải gói map theo phiên bản", "Downloads the exact stored ZIP for `id`; response includes a SHA-256 ETag for the immutable package. Current permission is Staff or TechnicalStaff. Downloading does not deploy the package. Missing version returns 404. " + JwtErrors),
            ["MapPoiController.RecordDeployment"] = ("[Technical Staff] Ghi nhận kiểm tra triển khai map", "Appends a manual deployment/localization/display check for map version `id`. Body fields include `requestId` (reuse unchanged for retry of the same payload), `robotCode`, exact `packageSha256`, `localizationPassed`, `displayPassed`, and required `evidenceNote`. Requires TechnicalStaff. The backend verifies the referenced physical robot and exact package checksum; saving records that a human performed and reported the check. It does not load a map or control a robot. Invalid evidence returns 400; missing robot/version 404; conflicting idempotency or deployment state 409. " + JwtErrors),
            ["MapPoiController.ListDeploymentChecks"] = ("[Technical Staff] Xem lịch sử kiểm tra triển khai map", "Returns append-only manual deployment-check records for map version `id`. Requires TechnicalStaff. The history records who submitted each check and does not query the robot. Missing version returns 404. " + JwtErrors),
            ["MapPoiController.CreateProposal"] = ("[Tour Staff] Tạo đề xuất POI chưa kiểm chứng", "Creates a POI proposal and its first draft revision only when the exact map version has an effective successful manual technical check: the latest record for at least one physical robot must match the package checksum and pass localization and display. Upload/ZIP validation alone is not sufficient. Creation remains NOT_CHECKED for POI verification. A currently ineligible map returns 409 with a business reason; failed mutations create no proposal, revision, submission receipt or success audit. Requires Staff (Tour Staff product label). Invalid pose or request returns 400; missing map returns 404; reused requestId with different content returns 409. " + JwtErrors),
            ["MapPoiController.ListProposals"] = ("[Tour Staff/Technical Staff] Liệt kê đề xuất POI", "Lists proposals, optionally filtered by `mapVersionId`. Current read permission is Staff or TechnicalStaff. Results include current revision and technical status; submitting a proposal does not itself verify it. Invalid filter/input returns 400. " + JwtErrors),
            ["MapPoiController.GetProposal"] = ("[Tour Staff/Technical Staff] Xem đề xuất POI và trạng thái", "Reads a proposal by `id`, including its current `revision`, `rowVersion`, map version and verification status. Current read permission is Staff or TechnicalStaff. Missing proposal returns 404. " + JwtErrors),
            ["MapPoiController.GetProposalHistory"] = ("[Tour Staff/Technical Staff] Xem lịch sử revision và kiểm chứng POI", "Returns immutable revisions and recorded verification history for proposal `id`. Current read permission is Staff or TechnicalStaff. History is scoped to the submitted revision/fingerprint and evidence captured for it. Missing proposal returns 404. " + JwtErrors),
            ["MapPoiController.ReviseProposal"] = ("[Tour Staff] Tạo revision nháp cho đề xuất POI", "Creates the next immutable draft revision only while the exact map version remains eligible for POI preparation. This gate applies also when changing the revision to another map. Body includes `requestId`, `expectedCurrentRevision`, `expectedRowVersion`, and draft fields including `mapVersionId`. Ineligible map state returns 409 with a reason. Requires Staff. Stale revision/rowVersion conflicts return 409. A movement-affecting change has a different navigation fingerprint and needs new POI technical verification; old revisions/results remain readable. " + JwtErrors),
            ["MapPoiController.SubmitProposal"] = ("[Tour Staff] Gửi revision POI để kiểm chứng", "Submits the current draft revision only while its exact map version remains eligible for POI preparation. Body includes `requestId`, `expectedRevisionNumber`, and `expectedRowVersion`. Ineligible map state returns 409 with a reason. Requires Staff. Submission does not mean the POI has passed. A stale or already-submitted state returns 409. " + JwtErrors),
            ["MapPoiController.DiscardProposal"] = ("[Tour Staff] Xoá POI chưa từng đạt khỏi danh sách", "Soft-discards a POI proposal that has no PASS result on any revision (draft, waiting for technical verification, or needs fix). Body includes `expectedRevisionNumber` and `expectedRowVersion`. Nothing is deleted: revisions, submissions, results and import receipts remain readable by id and history, while staff lists and the verification queue omit the proposal. A proposal with any PASS returns 409 `POI_PROPOSAL_HAS_PASS`; a stale version returns 409 `STALE_VERSION`; repeating the request for an already discarded proposal returns it unchanged. Later revise, submit, verify or re-import of the same source id returns 409 `POI_PROPOSAL_DISCARDED`. Requires Staff. " + JwtErrors),
            ["MapPoiController.VerificationQueue"] = ("[Technical Staff] Xem hàng đợi kiểm chứng POI", "Lists submitted current POI revisions that still need a result, optionally filtered by `mapVersionId`. Requires TechnicalStaff. Queue eligibility is based on the current revision and its navigation fingerprint; a prior result remains tied to its revision/fingerprint and is not copied to a changed movement configuration. " + JwtErrors),
            ["MapPoiController.RecordVerification"] = ("[Technical Staff] Ghi nhận PASS/FAIL cho revision POI", "Appends one technical result for proposal `id` and `revisionNumber`. Body includes `requestId`, `expectedRevisionNumber`, `expectedRowVersion`, `robotCode`, `resultCode`, reach/stop/localization/camera observations, and evidence or failure reason. Requires TechnicalStaff. PASS requires all required observations and matching deployed-map evidence for the exact `mapVersionId`/checksum and navigation fingerprint; FAIL requires a failed observation and reason. This is recorded human evidence, not proof the backend executed a physical test. Stale state/already-recorded result returns 409; missing map/robot/proposal returns 404; invalid evidence returns 400. " + JwtErrors),

            ["StaffRoutesController.List"] = ("[Tour Staff] Liệt kê tuyến phục vụ Tour hiện hành", "Lists the read-only Route catalog where `AuthoringMode=LEGACY` for the current Tour flow. This endpoint does not create a Route or Route revision. To create a versioned Route revision, use `POST /api/staff/routes` or `POST /api/staff/routes/{routeId}/revisions`; to view a specific Route's revision, use `GET /api/routes/{routeId}/revisions`. The versioned Route catalog is `GET /api/routes`. Requires Staff (product label: Tour Staff). " + JwtErrors),
            ["StaffRoutesController.Get"] = ("[Tour Staff] Xem chi tiết tuyến phục vụ Tour hiện hành", "Reads one persisted Route with `AuthoringMode=LEGACY` for the current Tour flow. This response is not a RouteRevision and does not certify a map/POI tuple. To create a versioned Route revision, use `POST /api/staff/routes/{routeId}/revisions`; to view a specific Route's revision, use `GET /api/routes/{routeId}/revisions`. Requires Staff (product label: Tour Staff). " + JwtErrors),

            ["RouteRevisionsController.ScheduledTours"] = ("[Tour Staff] Xem Tour đã lên lịch trên tuyến", "Lists SCHEDULED and READY Tours of a VERSIONED route so Staff can see them before deactivating it. Read-only. Requires Staff. A legacy or missing Route returns 404. " + JwtErrors),
            ["RouteRevisionsController.Deactivate"] = ("[Tour Staff] Ngừng sử dụng tuyến VERSIONED", "Stops new Tours on a VERSIONED route (ADR-0037). Body: `requestId`, `expectedRowVersion` (the route view's opaque `rowVersion`). Always allowed; it cancels no Tour and changes no revision, test run or PASS, and the response lists SCHEDULED and READY Tours on the route. A matching retry replays. A legacy or missing Route returns 404; stale token or reused requestId 409. Requires Staff. " + JwtErrors),
            ["RouteRevisionsController.Activate"] = ("[Tour Staff] Mở lại tuyến VERSIONED", "Lifts the stop on a VERSIONED route (ADR-0037); same body and errors as deactivate. Tour create still requires an effective PASS. Requires Staff. " + JwtErrors),
            ["RouteRevisionsController.Create"] = ("[Tour Staff] Tạo tuyến revision nháp", "Creates a versioned route identity and immutable revision 1 from `mapVersionId` and exact `poiRevisionId` values. Requires Staff (product label Tour Staff). Each selected POI must have an effective navigation PASS for the same exact map version; request includes `requestId`, `expectedCurrentRevision=0`, route poses, ordered stops and dwell. This stores manual preparation data only; it does not submit, verify, schedule or activate a tour. Invalid pose/input returns 400; missing IDs 404; stale, reused idempotency key, mismatched map or missing/currently superseded POI PASS returns 409. " + JwtErrors),
            ["RouteRevisionsController.Revise"] = ("[Tour Staff] Tạo route revision tiếp theo", "Appends an immutable draft revision under the existing versioned Route ID. `expectedCurrentRevision` protects concurrent edits; map/POI revision IDs are exact references, never resolved to latest by read. A new navigation fingerprint requires its own whole-route test; earlier revisions and test evidence remain available. Requires Staff. Validation returns 400; missing Route/map/POI 404; stale revision, invalidated POI evidence or idempotency conflict 409. " + JwtErrors),
            ["RouteRevisionsController.Submit"] = ("[Tour Staff] Gửi revision để kiểm tra tuyến", "Appends a submission receipt for the exact current `revisionId`; body contains `requestId` and `expectedCurrentRevision`. All selected POI verification evidence must still be the effective PASS. Requires Staff. Submission is separate from technical result and does not set READY or schedule a Tour. Missing records return 404; stale state, already-submitted revision or invalidated POI evidence return 409. " + JwtErrors),
            ["RouteRevisionsController.History"] = ("[Tour Staff/Technical Staff] Xem revision và lịch sử kiểm tra tuyến", "Reads the requested `revisionId` (or current revision if omitted), exact map/checksum, ordered POI revision and source-evidence IDs, submission state, manual test records and current route-test result. `includeHistory` controls whether all test runs are returned. Requires Staff or TechnicalStaff. `durationStatus=INCOMPLETE_CONTENT_AUDIO_DATA` means the new approved content/audio duration source is not yet implemented; dwell sum is reported separately and is not represented as total tour duration. Missing Route/revision returns 404. " + JwtErrors),
            ["RouteRevisionsController.Queue"] = ("[Technical Staff] Xem hàng đợi kiểm tra toàn tuyến", "Lists submitted versioned route revisions that have no whole-route test run yet. Requires TechnicalStaff; Staff cannot record technical results. Each item includes exact revision, map/checksum, POI revisions and source POI PASS evidence. This is a human test queue, not robot dispatch. " + JwtErrors),
            ["RouteRevisionsController.Participants"] = ("[Technical Staff] Liệt kê Staff có thể đi cùng khi chạy thử", "Lists active single-role Staff accounts that a whole-route test run can name as participant. Read-only; it does not assign an Operator or grant any permission."),
            ["RouteRevisionsController.RecordRun"] = ("[Technical Staff] Ghi nhận PASS/FAIL chạy thử toàn tuyến", "Appends manual whole-route test evidence for a submitted exact `revisionId`. Body fields include `requestId`, physical `robotCode`, distinct active participating Staff account, `resultCode`, all-stop/localization/safe-stop observations, measured duration, evidence and failure reason. The backend locks and checks the robot's latest manual deployment evidence across maps and requires the exact map version/checksum. PASS requires every route observation; FAIL requires a reason and a failed observation. This records human evidence, not robot control or proof beyond submitted observations. Missing records return 404; invalid input 400; role 403; stale deployment/POI state, retry-content conflict or invalid workflow 409. " + JwtErrors),

            ["StaffToursController.List"] = ("[Tour Staff] Liệt kê Tour", "Lists persisted Tours with paging and optional state, phase (UPCOMING, RUNNING, FINISHED), and time filters. Each row has a read-only `execution` summary: `operationalStatus`, `assistanceReason`, `currentStep`, `commandState` (the current leg's GoTo, as in the detail) and `needsReconcile` (a GoTo of this Tour is UNKNOWN, also after End Early). " + TourStorageBoundary + " A listed Tour is not evidence that it is ready to run."),
            ["StaffToursController.Get"] = ("[Tour Staff] Xem chi tiết Tour", "Reads Tour `id` and its Route details; a missing Tour returns 404. A Tour with `routeRevision` has null `route` and `activeRoute`. `permissions.canMarkReady`, `canReopen` and `readyBlockers` (`code`, Vietnamese `message`) show the READY conditions now; Mark READY rechecks them. " + TourStorageBoundary + " " + JwtErrors),
            ["StaffToursController.Create"] = ("[Tour Staff] Tạo Tour", "Creates a SCHEDULED Tour from one exact submitted RouteRevision with an effective PASS run, one physical robot and one active Staff Operator. The robot is reserved from 15 minutes before the start until the measured PASS duration plus 15 minutes after (ADR-0034). With `shortNoticeReason` (required for it, at most 500 characters) and no `scheduledStartAt`, it is a quick Tour (ADR-0053): no shift, the robot held from now until the latest Start (now plus `Tours:ShortNoticeMinLeadMinutes`, 30 by default) plus the expected duration plus 15 minutes, published at that latest Start, and Start opens at creation; `SHIFT_BLOCKED` when the hold reaches a closed day or shift. Overlap returns `ROBOT_RESERVATION_CONFLICT` (409); an untested revision returns `ROUTE_TEST_PASS_REQUIRED` (409). " + TourStorageBoundary + " " + JwtErrors),
            ["StaffToursController.Operators"] = ("[Tour Staff] Liệt kê Staff có thể vận hành Tour", "Lists active single-role Staff accounts that a new Tour can name as Operator. Read-only; it grants no per-Tour permission. " + JwtErrors),
            ["StaffToursController.Update"] = ("[Tour Staff] Cập nhật Tour", "Updates Tour `id` using the current lifecycle and row-version rules. Metadata-only edits are allowed for eligible existing Tours. Changing the scheduled time or Route is blocked with `TOUR_DURATION_UNAVAILABLE` (409); cancel and recreate instead (ADR-0034). " + TourStorageBoundary + " " + JwtErrors),
            ["StaffToursController.Cancel"] = ("[Tour Staff] Hủy Tour trước Start", "Cancels a Tour in SCHEDULED or READY state before Start using the current row-version and lifecycle conditions. Cancellation revokes invitation access and closes existing sessions. This endpoint does not perform runtime End Early; no robot reservation exists to release. " + TourStorageBoundary + " " + JwtErrors),
            ["StaffToursController.MarkReady"] = ("[Tour Staff] Chuyển Tour sang READY", "Body `{requestId, expectedRowVersion}`. Moves a SCHEDULED versioned Tour to READY after every READY condition of architecture §3.2 passes under the Tour lock (ADR-0042). Any failing condition returns `READY_PRECONDITION_FAILED` (409) with every `blockers` entry; stale version `STALE_VERSION`, reused request `IDEMPOTENCY_CONFLICT`. READY locks registration, row review, email change and metadata until Reopen. It does not start the Tour, claim the robot or send a command. " + JwtErrors),
            ["StaffToursController.Reopen"] = ("[Tour Staff] Mở lại Tour READY về SCHEDULED", "Body `{requestId, expectedRowVersion, reason}`. Returns a READY Tour that has not started to SCHEDULED and records the reason. Reservation, registrations and invitations are unchanged. Another state returns `TOUR_STATE_INVALID` (409). " + JwtErrors),
            ["StaffToursController.StartChecks"] = ("[Tour Staff] Xem checklist trước Start", "Any Staff. Returns `{checks: [{id, passed, source, detail}], canStart, blockedBy}`: the Start conditions of architecture §3.2 evaluated now without locks, from DB, in-memory Fleet Sync telemetry, configuration and console presence (`source` DB, TELEMETRY, CONFIG, CONSOLE). `callerIsOperator` tells whether the viewer is the Tour's Operator and is a root cause for anyone else, while every other check still runs; the four on-site confirmations exist only in Start. `canStart` is the caller's own answer: true only when every returned check passed; `blockedBy` lists root causes only, and a check skipped because another failed shows `passed: false` without being listed. While `FleetCommands:Enabled` is false (the default) `commandTransportEnabled` fails. Missing Tour 404. " + JwtErrors),
            ["StaffToursController.Start"] = ("[Tour Staff] Start Tour", "Body `{requestId, expectedRowVersion, confirmation: {robotPlaced, areaClear, attendantPresent, previewChecked}}`. Only the Tour's Operator (other Staff 403). Start is accepted from `FleetCommands:StartEarlyLimitMinutes` (default 10, at most 15) before the published time (a quick Tour from its creation, when its robot hold opens, ADR-0053) until `StartLateLimitMinutes` (default 15, at most 15) after it; before the published time the `allViewersJoined` check needs every accepted row in the waiting room (ADR-0050). Runs every Start check under the Tour lock: a failing check returns 409 `START_PRECONDITION_FAILED` with `errors.checks` and `errors.blockedBy`; if only the command transport is off (the default) it returns 409 `COMMAND_TRANSPORT_DISABLED` with the checks and writes nothing. Otherwise one transaction claims the robot, moves the Tour to RUNNING and stores the first GoTo as PENDING; `ROBOT_CLAIM_FAILED` (409) if the robot just changed, `STALE_VERSION` on an old version. A repeat with the same `requestId` returns the earlier result. Storing a command does not prove a robot moved (ADR-0042, ADR-0043). " + JwtErrors),
            ["StaffToursController.EndEarly"] = ("[Tour Staff] Kết thúc sớm Tour", "Body `{requestId, expectedRowVersion, reason}`. Only the Tour's Operator, while RUNNING (`TOUR_STATE_INVALID`). The Tour becomes CANCELLED and the robot `NeedsInspection = 1` and stays held. An undelivered GoTo is withdrawn; a delivered or accepted one gets a Cancel; the leg's real result is still recorded later. Nothing in this flow proves the robot stopped; on-site Technical Staff release it. Live, fallback and Q&A revocation (FR-48) is a follow-up. " + JwtErrors),
            ["StaffToursController.RetryLeg"] = ("[Tour Staff] Thử lại chặng", "Body `{requestId, expectedRowVersion}`. Only the Tour's Operator, while NEEDS_ASSISTANCE after a GoTo that FAILED (`NavigationFailed`) or was REJECTED (`CommandRejected`); otherwise `TOUR_RETRY_NOT_ALLOWED` (409), always for UNKNOWN or RECONCILED. A new GoTo with a new leg to the same target after the movement checks: `MOVE_PRECONDITION_FAILED` (409) with `errors.checks` and `errors.blockedBy`. " + JwtErrors),
            ["StaffToursController.Reconcile"] = ("[Tour Staff] Đối soát lệnh UNKNOWN", "Body `{requestId, reason}`. Only the Tour's Operator, for an UNKNOWN GoTo of this Tour (`COMMAND_STATE_INVALID`, 409). Records RECONCILED: the real outcome stays unknown, the robot gets `NeedsInspection = 1` and a running Tour stays NEEDS_ASSISTANCE, so only End Early remains. " + JwtErrors),
            ["StaffToursController.QueueHeadCommand"] = ("[Tour Staff] Xoay đầu quay của robot", "ADR-0045. Body `{kind, panSteps, tiltSteps, panDir, tiltDir, panDeg, tiltDeg, sweepDeg}`, at most 4 KB; only the fields of `kind` (STEP, JOG, STOP, ANGLE, SWEEP) may be set; ANGLE stays within pan ±170 and tilt ±18; SWEEP may carry `sweepDeg` (10..170 per side) and makes the head look left, right and back. Only the Tour's Operator (other Staff 403), while the Tour is RUNNING (`TOUR_STATE_INVALID`). 409 `HEAD_CONTROL_DISABLED` while `FleetHead:Enabled = false`; 409 `HEAD_ROBOT_NOT_CONNECTED` when the robot has not polled within `FleetHead:RobotConnectedWithinMs`. Returns `{seq, robotCode, issuedAt}`: queued in memory, not proof the head moved. No SQL write and no per-press audit. " + JwtErrors),
            ["StaffToursController.SetHeadMode"] = ("[Tour Staff] Chọn chế độ đầu quay (tự động/bằng tay)", "ADR-0045 addendum. Body `{mode}`: `AUTO` does what each POI's camera preset says at arrival (turn to FRONT/LEFT/RIGHT or a custom angle, sweep left, right and back, or nothing for NONE) and turns the head to the front when Next starts the following leg; `MANUAL` only follows the buttons. Buttons work in both modes and stop a running sweep. Only the Tour's Operator (other Staff 403), until the Tour is COMPLETED or CANCELLED (`TOUR_STATE_INVALID`). In memory: a Tour never set, or any Tour after an API restart, has `FleetHead:DefaultMode` (AUTO). Returns `{tourId, mode}`. " + JwtErrors),
            ["StaffToursController.GetHeadStatus"] = ("[Tour Staff] Xem trạng thái đầu quay", "ADR-0045. Returns `{enabled, mode, robotCode, connected, lastPollAt, head, headReceivedAt}` for the Tour's robot: whether head control is on, the Tour's head mode (AUTO or MANUAL), whether the robot is polling, and the last head state it reported. Any Staff. A missing Tour returns 404. Read from memory; it is not a Tour state. " + JwtErrors),
            ["StaffToursController.Next"] = ("[Tour Staff] Đi tiếp sau POI", "Body `{requestId, expectedRowVersion}`. Only the Tour's Operator (other Staff 403), while RUNNING, NORMAL and OBSERVING (`TOUR_STATE_INVALID`) with no open command (`TOUR_COMMAND_OPEN`). Closes the visit, then stores a GoTo to the next stop or the end pose, or completes the Tour and releases the robot when the route ends at its last POI. A new command needs the movement checks: 409 `MOVE_PRECONDITION_FAILED` with `errors.checks` and `errors.blockedBy`. " + JwtErrors),

            ["StaffRegistrationsController.List"] = ("[Tour Staff] Liệt kê hồ sơ và dòng đang chờ", "Lists registration summaries; `state=SUBMITTED` includes any registration with an active PENDING row, including a mixed registration whose aggregate is APPROVED. Open detail for per-row permissions and current row versions. Review age comes from `submittedAt`; pending row/email decisions remain separate from delivery or session state. Requires Staff JWT. Invalid filters return 400; unauthorized roles 401/403. " + JwtErrors),
            ["StaffRegistrationsController.Get"] = ("[Tour Staff] Xem trạng thái từng dòng đăng ký", "Reads registration and current row IDs, `participationState`, rowVersion, review metadata and per-row action eligibility. Requires Staff JWT. Review each row through its accept/reject action; aggregate registration decisions are not exposed." + JwtErrors),
            ["StaffRegistrationsController.AcceptRow"] = ("[Tour Staff] Chấp nhận một điểm xem", "Accepts only the active PENDING row identified by `rowId`. Body includes `requestId`, expected Tour/registration/row rowVersions. Only Staff may review; acceptance changes that row to ACCEPTED and makes it eligible for its own invitation. Stale/state conflicts return 409; unknown registration/row returns 404; invalid input 400." + JwtErrors),
            ["StaffRegistrationsController.RejectRow"] = ("[Tour Staff] Từ chối một điểm xem", "Rejects only the active PENDING row identified by `rowId`; body requires `requestId`, expected Tour/registration/row rowVersions and a reason. Other rows and credentials remain unchanged. Stale/state conflicts return 409; unknown registration/row returns 404; invalid input 400." + JwtErrors),
            ["StaffRegistrationsController.EmailChangeRequests"] = ("[Tour Staff] Liệt kê yêu cầu đổi email", "Lists email-change requests with old/proposed addresses and review versions; the endpoint is Staff-only and does not mutate invitation access." + JwtErrors),
            ["StaffRegistrationsController.EmailChangeRequest"] = ("[Tour Staff] Xem yêu cầu đổi email", "Reads the request and current request/Tour/registration/row versions needed for a conditional review. Missing request returns 404; only Staff may view." + JwtErrors),
            ["StaffRegistrationsController.AcceptEmailChange"] = ("[Tour Staff] Chấp nhận yêu cầu đổi email", "Accepts a pending request using its request rowVersion plus expected Tour/registration/row versions. In one Tour-first transaction it updates only the target row, rotates its invitation credential and closes its old browser session; delivery is queued after commit. Stale/conflicting state returns 409; invalid input 400; missing request 404." + JwtErrors),
            ["StaffRegistrationsController.RejectEmailChange"] = ("[Tour Staff] Từ chối yêu cầu đổi email", "Rejects a pending email-change request using version guards and optional reason. The approved email, current credential and session remain unchanged. Stale/conflicting state returns 409; invalid input 400; missing request 404." + JwtErrors),

            ["AuthController.Login"] = ("Đăng nhập và nhận access token", "Authenticates username/password and sets the refresh-token cookie. Anonymous endpoint; request origin must be allowed by backend configuration. Invalid credentials are rejected; login rate limiting applies. The response contains the JWT `accessToken` and role."),
            ["AuthController.Refresh"] = ("Làm mới phiên đăng nhập", "Uses the HttpOnly refresh cookie to issue a new access token and refresh cookie. Anonymous transport endpoint; the cookie and allowed request origin are required. Invalid/expired or blocked sessions return 401/403 and clear the refresh cookie."),
            ["AuthController.Logout"] = ("Đăng xuất và thu hồi refresh token", "Revokes the refresh token presented in the HttpOnly cookie when valid, then clears the cookie. Anonymous transport endpoint; request origin must be allowed. Returns 204 after processing."),
            ["FleetCommandsController.Poll"] = ("[Robot] Lấy lệnh hiện tại", "Body `{streamId}`. Robot scheme only (`Authorization: Bearer`, `X-Robot-Code`); user JWTs get 401. Returns `data.command`: null, a GoTo or a Cancel, per docs/contracts/fleet-commands/v1. `streamId` must be the robot's current Fleet Sync stream, heard within `FleetCommands:MaxTelemetryAgeSeconds`, otherwise 409 `STREAM_NOT_CURRENT` and nothing is delivered. Repeating the poll returns the same command. A command delivered to an earlier stream becomes UNKNOWN and is never redelivered. A GoTo is handed out only while `FleetCommands:Enabled = true`, and a new one needs a RUNNING NORMAL Tour and a robot with `IsDispatchEnabled = 1`; a Cancel is always delivered, also while commands are off. Shares the FleetSync rate limit."),
            ["FleetCommandsController.Results"] = ("[Robot] Báo kết quả lệnh", "Body `{commandId, legId, streamId, reportedAt, phase, outcome, reason}`; `commandId` must equal the path (400). Answered only after the state change and its TourEvent commit: `data` is `{accepted, duplicate, commandState}`. An exact repeat returns `duplicate: true` with no effect. 404 `COMMAND_NOT_FOUND` for an unknown command or another robot's; 409 `RESULT_CONFLICT`, `RESULT_STREAM_MISMATCH`, `RESULT_PHASE_NOT_ALLOWED`. Recorded also while commands are off. Shares the FleetSync rate limit."),
            ["FleetHeadController.Poll"] = ("[Robot] Long poll lệnh xoay đầu quay", "Body `{epoch, afterSeq, waitMs, head}`, at most 4 KB. Robot scheme only (`Authorization: Bearer`, `X-Robot-Code`); user JWTs get 401. Holds up to `FleetHead:MaxWaitMs` and returns `data.epoch` and the queued head commands after `afterSeq` (STEP, JOG, STOP or ANGLE, per docs/contracts/fleet-head/v1). A changed epoch means the API restarted and earlier commands are gone. Commands older than `FleetHead:MaxCommandAgeMs` are never delivered. The optional `head` reports the head's state for Staff. Answers also while `FleetHead:Enabled = false`. Has its own `FleetHead` rate limit, separate from Fleet Sync."),
            ["FleetCameraController.Poll"] = ("[Robot] Hỏi có cần bật camera Quest không", "ADR-0052. Optional JSON body (ADR-0056), at most 1 KB: `{headset: {connection, batteryPercent, charging, stream}}`, the headset as quest-stream read it over adb; unknown words become `unknown` and the battery is clamped to 0–100, so a bad field never fails the poll. An older robot sends no body. Robot scheme only (`Authorization: Bearer`, `X-Robot-Code`); user JWTs get 401. Returns `data` as `{wanted, reason, pollSeconds}`: `reason` is `TOUR_RUNNING`, `STAFF_WATCHING` or `IDLE`. The robot captures and publishes only while `wanted` is true and polls again after `pollSeconds`. No SQL write. Shares the FleetSync rate limit."),
            ["StaffRobotCameraController.Headset"] = ("[Tour Staff] Xem pin và kết nối kính Quest của robot", "ADR-0056. Returns `data` as `{robotCode, reported, connection, batteryPercent, charging, stream, reportedAt, stale}` from the headset report the robot sent with its last camera poll. `connection` is `connected`, `unauthorized`, `offline`, `not_found`, `adb_error` or `unknown`; `stream` is `live`, `connecting`, `paused`, `lost` or null. `reported` is false before the first report; `stale` is true when the last report is older than `FleetCamera:RobotListeningWithinSeconds` (the robot stopped polling, so the battery may be out of date). Held in memory; an API restart forgets it until the next poll. Requires Staff. Invalid `robotCode` returns 400; unknown robot returns 404. " + JwtErrors),
            ["StaffRobotCameraController.Lease"] = ("[Tour Staff] Gia hạn lease camera của robot", "ADR-0052. No body. Keeps the camera of `robotCode` on for `FleetCamera:LeaseSeconds`; the pre-start check page renews it every 30 s. Returns `data` as `{robotCode, wanted, reason, robotListening, lastPollAt, leaseUntil, stream}`. `stream` is `{whepUrl, token, expiresAt}` (ADR-0055) when the public relay carries this robot, otherwise null; connect to `whepUrl?token=…` before `expiresAt`, and each renewal brings a new token. `robotListening` only means the robot polled within `FleetCamera:RobotListeningWithinSeconds`, not that video is flowing. The lease is held in memory; no SQL write. Requires Staff. Invalid `robotCode` returns 400; unknown robot returns 404. " + JwtErrors),
            ["FleetSyncController.Sync"] = ("[Robot] Gửi telemetry lên Fleet Sync", "Accepts an authenticated robot telemetry report over the dedicated robot credential scheme, not a user JWT. `StreamId` and `Seq` support duplicate reconciliation; `ReportedAt`, map/frame, pose, status and health fields carry telemetry. This endpoint is telemetry-only and returns no movement commands. Invalid reports return 400; invalid robot credentials return 401; rate limiting may return 429."),
            ["InvitationsController.Get"] = ("[Staff/Representative] Xem lời mời trong phạm vi hồ sơ", "Reads invitation records for `registrationId`. Staff can manage registrations; Representative access is scoped to their own registration. Requires Staff or Representative JWT. Missing/out-of-scope records return 404/403 as enforced by the handler."),
            ["InvitationsController.Issue"] = ("[Staff/Representative] Phát hành lời mời cho dòng đã duyệt", "Issues invitations only for active ACCEPTED rows that do not already have an invitation. A PENDING/REJECTED row never receives access. Representative is limited to their own registration; Staff requires Staff role. " + JwtErrors),
            ["InvitationsController.Resend"] = ("[Staff/Representative] Gửi lại cùng mã lời mời", "Queues delivery to the currently approved row email using the same current code and `AccessVersion`; it keeps the existing browser session. Does not approve a row or extend eligibility. Representative is owner-scoped; Staff requires Staff role." + JwtErrors),
            ["InvitationsController.Reissue"] = ("[Staff/Representative] Đổi mã và đóng phiên cũ", "Reissues the credential, increases `AccessVersion`, and closes the target invitation's existing session. The old code/session stop working; this differs from Resend. Representative is owner-scoped; Staff requires Staff role." + JwtErrors),
            ["InvitationsController.Revoke"] = ("[Staff/Representative] Thu hồi lời mời", "Revokes the invitation identified by `invitationId` within `registrationId`. Requires Staff or the owning Representative. Successful revocation affects subsequent access checks; missing/out-of-scope or conflicting state returns 403/404/409 as applicable."),
            ["RepresentativeController.Tours"] = ("[Representative] Xem danh sách tour có thể đăng ký", "Lists tours available to the authenticated Representative with standard paging/search filters. Requires Representative JWT. Invalid paging/filter values return 400."),
            ["RepresentativeController.Tour"] = ("[Representative] Xem tour", "Reads tour details by `id` for an authenticated Representative. Requires Representative JWT; missing or inaccessible tour returns 404/403 as enforced by the query."),
            ["RepresentativeController.Registrations"] = ("[Representative] Xem danh sách đăng ký của mình", "Lists the current Representative's registrations, optionally filtered by tour, state and group. Requires Representative JWT; results are owner-scoped."),
            ["RepresentativeController.Registration"] = ("[Representative] Xem chi tiết đăng ký của mình", "Reads registration details by `id` for its owning Representative. Requires Representative JWT; another owner's registration is not accessible."),
            ["RepresentativeController.Submit"] = ("[Representative] Gửi hồ sơ tối đa 10 điểm xem", "Creates one registration per Representative/Tour with 1–10 viewing-point rows. Shared-screen rows count as one viewing point, not the number of students watching. New rows are PENDING; the 48-hour cutoff is checked under the Tour lock. Requires the owner's Representative JWT and `Idempotency-Key`. Invalid input 400; cutoff/duplicate/state conflict 409; missing Tour 404." + JwtErrors),
            ["RepresentativeController.Update"] = ("[Representative] Cập nhật danh sách theo RowId", "Submits a stable-row diff: each supplied existing `rowId` retains that row, an omitted active row is explicitly removed (and only its own invitation/session is revoked), and an item without `rowId` creates a new PENDING row. Removals and additions may be mixed in one request; unknown/inactive IDs return 409 and duplicate IDs/invalid fields return 400. Accepted-row email changes must use the request/review workflow. Adding is limited to 10 active viewing rows and blocked inside 48 hours; removals remain allowed." + JwtErrors),
            ["RepresentativeController.Resubmit"] = ("[Representative] Gửi lại đăng ký", "Resubmits registration `id` after correction using the replacement request. Requires owning Representative JWT and an eligible current state; invalid or conflicting state returns 400/403/409."),
            ["RepresentativeController.Cancel"] = ("[Representative] Hủy đăng ký", "Cancels registration `id` using the request/reason. Requires owning Representative JWT and an eligible registration state; missing, unauthorized or conflicting state returns 403/404/409."),
            ["RepresentativeController.RequestEmailChange"] = ("[Representative] Yêu cầu đổi email của điểm xem", "Creates one pending request per ACCEPTED row with the row ID, old/proposed address, requester and row/Tour/registration versions. Same `requestId` and content replays the existing request ID; a different request while one is PENDING returns 409 `EMAIL_CHANGE_PENDING` and does not replace it. The old email, code and session remain effective until Staff accepts. Request ID makes retries safe; row must be ACCEPTED and Tour SCHEDULED. Invalid input 400; stale/duplicate/reservation state 409; inaccessible row 404." + JwtErrors),
            ["RepresentativeController.EmailChangeRequests"] = ("[Representative] Xem yêu cầu đổi email của mình", "Lists requests only for a registration owned by the authenticated Representative. It does not show requests from another group or create a Viewer account." + JwtErrors),
            ["StudentAccessController.Join"] = ("[Viewer] Tham gia tour bằng lời mời", "Exchanges an access code for the tour-scoped HttpOnly Viewer session cookie. No Viewer account or JWT is created. Requires an eligible invitation and allowed request origin; code/eligibility failures return 400/401/403, and join rate limiting may return 429."),
            ["StudentAccessController.Session"] = ("[Viewer] Khôi phục phiên tour", "Validates the session cookie and its browser-bound device cookie, or the device cookie alone after a network reconnect. Reconnect/heartbeat is allowed only when the active session was last seen within 2 minutes; the configured 10-minute idle lease does not extend this reconnect grace. A session cookie for an older session cannot bypass the grace window. One invitation has at most one active browser session; another browser cannot take it over. Missing, expired, revoked or out-of-window credentials are rejected."),
            ["StudentAccessController.Leave"] = ("[Viewer] Rời phiên tour", "Ends the current tour-scoped Viewer session and clears its cookie. Anonymous cookie-based endpoint; session revocation affects subsequent requests."),
            ["StudentTourController.StreamAccess"] = ("[Viewer] Lấy địa chỉ và token xem hình trực tiếp", "ADR-0055. Viewer session cookie only. Returns `data` as `{whepUrl, token, expiresAt}` (token life `QuestRelay:TokenSeconds`, default 120 s, at most 300) while the Tour is RUNNING on the relay's robot or SCHEDULED/READY with a reservation on it; the page connects to `whepUrl?token=…` and asks again before `expiresAt`. Missing, expired or revoked session returns 401; a Tour that ended, was cancelled or uses another robot, or a server without `QuestRelay`, returns 409 `STREAM_NOT_AVAILABLE`. Not cached."),
